1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.OwnerCityAtCapacityException;
8	
9	/**
10	 * Rejects a create request when the owner's city already contains 50 or more owners,
11	 * comparing city names case-insensitively with collapsed whitespace. Runs after
12	 * {@link ValidateOwnerFields}, so it sees the validated request, and before
13	 * {@link BuildOwner}, so an at-capacity city is a 409 rather than a persisted record.
14	 */
15	public class CheckOwnerCityCapacity {
16	
17	    /** Cities at or above this many owners reject further creates. */
18	    private static final int CITY_CAPACITY = 50;
19	
20	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
21	            throws OwnerCityAtCapacityException {
22	        String city = normalize(request.getCity());
23	        int count = 0;
24	        for (Owner existing : ownerRepository.findAll()) {
25	            if (city.equals(normalize(existing.getCity()))) {
26	                count++;
27	            }
28	        }
29	        if (count >= CITY_CAPACITY) {
30	            throw new OwnerCityAtCapacityException(request.getCity(), count);
31	        }
32	    }
33	
34	    /** Lower-cased, trimmed, with internal whitespace runs collapsed to a single space. */
35	    private static String normalize(String value) {
36	        if (value == null) {
37	            return "";
38	        }
39	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
40	    }
41	}
