1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Assigns the owner's {@code capacityWarning}: {@code true} when the owner's city already
9	 * held between 40 and 49 owners at the moment this owner was created (approaching the hard
10	 * capacity limit of 50), {@code false} otherwise. Cities are compared case-insensitively
11	 * with collapsed whitespace, matching {@link CheckOwnerCityCapacity}. Runs after
12	 * {@link BuildOwner} (so the city is set) and before {@link SaveOwner} (so the count
13	 * reflects the owners that existed before this create and excludes the one being created).
14	 * The 50-owner hard rejection has already run in {@link CheckOwnerCityCapacity}, so the
15	 * count here is never 50 or more. The value is fixed at creation time and persisted with
16	 * the owner.
17	 */
18	public class AssignCapacityWarning {
19	
20	    /** Cities already holding at least this many owners raise the warning. */
21	    private static final int WARNING_THRESHOLD = 40;
22	
23	    /** Cities at or above this many owners are already rejected before this step. */
24	    private static final int CITY_CAPACITY = 50;
25	
26	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
27	        String city = normalize(owner.getCity());
28	        int count = 0;
29	        for (Owner existing : ownerRepository.findAll()) {
30	            if (city.equals(normalize(existing.getCity()))) {
31	                count++;
32	            }
33	        }
34	        owner.setCapacityWarning(count >= WARNING_THRESHOLD && count < CITY_CAPACITY);
35	    }
36	
37	    /** Lower-cased, trimmed, with internal whitespace runs collapsed to a single space. */
38	    private static String normalize(String value) {
39	        if (value == null) {
40	            return "";
41	        }
42	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
43	    }
44	}
