1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.IdentityKey;
5	import org.springframework.samples.petclinic.model.Owner;
6	import org.springframework.samples.petclinic.model.Soundex;
7	import org.springframework.samples.petclinic.repository.OwnerRepository;
8	
9	/**
10	 * Flags a soft (non-hard) duplicate. Runs after {@link CheckOwnerIdentityUnique} — so any
11	 * exact identity duplicate has already been rejected with 409 — and before {@link SaveOwner},
12	 * so the flags are computed against the owners that existed before this create and are
13	 * persisted with the new owner.
14	 *
15	 * <p>An owner is a possible duplicate when its {@code identityKey} <em>differs</em> from an
16	 * existing owner's while its {@code soundex(lastName)} and {@code postcode} both match. This
17	 * is exactly the case the identity key no longer treats as a hard duplicate: same household
18	 * (phonetic last name + postcode) but a different telephone (hence a different key). When
19	 * such an existing owner is found, {@code possibleDuplicate} is set true and
20	 * {@code possibleDuplicateOf} to that owner's id (the lowest id when several match);
21	 * otherwise {@code possibleDuplicate} is false and {@code possibleDuplicateOf} null. A
22	 * soft-deleted owner never matches, and a null postcode is never a possible duplicate.
23	 */
24	public class AssignPossibleDuplicate {
25	
26	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
27	        String identityKey = IdentityKey.of(owner);
28	        String soundex = Soundex.of(owner.getLastName());
29	        String postcode = owner.getPostcode();
30	
31	        Owner match = null;
32	        if (postcode != null) {
33	            for (Owner existing : ownerRepository.findAll()) {
34	                if (existing.isDeleted()) {
35	                    continue; // a soft-deleted owner is not a possible duplicate match
36	                }
37	                if (postcode.equals(existing.getPostcode())
38	                        && soundex.equals(Soundex.of(existing.getLastName()))
39	                        && !identityKey.equals(IdentityKey.of(existing))) {
40	                    if (match == null || existing.getId() < match.getId()) {
41	                        match = existing;
42	                    }
43	                }
44	            }
45	        }
46	
47	        if (match != null) {
48	            owner.setPossibleDuplicate(true);
49	            owner.setPossibleDuplicateOf(match.getId());
50	        }
51	        else {
52	            owner.setPossibleDuplicate(false);
53	            owner.setPossibleDuplicateOf(null);
54	        }
55	    }
56	}
