1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.IdentityKey;
5	import org.springframework.samples.petclinic.model.Owner;
6	import org.springframework.samples.petclinic.repository.OwnerRepository;
7	import org.springframework.samples.petclinic.rest.escalation.OwnerIdentityConflictException;
8	
9	/**
10	 * The duplicate-detection block, now keyed on the single {@link IdentityKey}: a create is
11	 * rejected (409) only when its {@code identityKey} — the SHA-256 over
12	 * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)} — equals that of
13	 * an existing owner. Soft-deleted owners are ignored, so they no longer block a duplicate.
14	 * The email-domain blocklist has already been applied (an invalid/disposable email is a 400
15	 * in {@link ValidateOwnerFields}), so this runs against a valid, normalized identity.
16	 *
17	 * <p>Because the telephone is part of the key, two owners sharing only a last name and
18	 * postcode with different telephones derive <em>different</em> keys — they are no longer a
19	 * hard household duplicate here but a soft match (see {@link AssignPossibleDuplicate}). The
20	 * former household-duplicate 409 keyed on {@code householdId} no longer applies.
21	 *
22	 * <p>Runs after {@link BuildOwner} (so the new owner carries its normalized telephone,
23	 * email and last name) and before {@link SaveOwner} (so a duplicate is a 409 rather than a
24	 * persisted record).
25	 */
26	public class CheckOwnerIdentityUnique {
27	
28	    public void service(@Val Owner owner, OwnerRepository ownerRepository)
29	            throws OwnerIdentityConflictException {
30	        String identityKey = IdentityKey.of(owner);
31	        for (Owner existing : ownerRepository.findAll()) {
32	            if (existing.isDeleted()) {
33	                continue; // a soft-deleted owner no longer blocks a duplicate
34	            }
35	            if (identityKey.equals(IdentityKey.of(existing))) {
36	                throw new OwnerIdentityConflictException(identityKey);
37	            }
38	        }
39	    }
40	}
