278	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
279	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
280	        return Collections.unmodifiableList(sortedPets);
281	    }
282	
283	    public void setPets(List<Pet> pets) {
284	        this.pets = new HashSet<>(pets);
285	    }
286	
287	    public void addPet(Pet pet) {
288	        getPetsInternal().add(pet);
289	        pet.setOwner(this);
290	    }
291	
292	    /**
293	     * Return the Pet with the given name, or null if none found for this Owner.
294	     *
295	     * @param name to test
296	     * @return true if pet name is already in use
297	     */
298	    public Pet getPet(String name) {
299	        return getPet(name, false);
300	    }
301	
302	    /**
303	     * Return the Pet with the given name, or null if none found for this Owner.
304	     *
305	     * @param name to test
306	     * @return true if pet name is already in use
307	     */
308	    public Pet getPet(String name, boolean ignoreNew) {
309	        name = name.toLowerCase();
310	        for (Pet pet : getPetsInternal()) {
311	            if (!ignoreNew || !pet.isNew()) {
312	                String compName = pet.getName();
313	                compName = compName.toLowerCase();
314	                if (compName.equals(name)) {
315	                    return pet;
316	                }
317	            }
318	        }
319	        return null;
320	    }
321	
322	    public Pet getPet(Integer petId) {
323	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
324	    }
325	
326	    @Override
327	    public String toString() {
328	        return new ToStringCreator(this)
329	
330	            .append("id", this.getId())
331	            .append("new", this.isNew())
332	            .append("lastName", this.getLastName())
333	            .append("firstName", this.getFirstName())
334	            .append("address", this.address)
335	            .append("city", this.city)
336	            .append("telephone", this.telephone)
337	            .append("email", this.email)
338	            .toString();
339	    }
340	}
